/* Local AI Document Reader site behaviour. No dependencies. Data: window.LLE from data/site-data.js (generated by
   build_data.py from exports/ and the SYNTHETIC PDFs). Everything here is progressive: pages read fine without it. */
(function () {
  "use strict";
  const D = window.LLE || null;
  const rm = window.matchMedia("(prefers-reduced-motion: reduce)");
  const $ = (s, el) => (el || document).querySelector(s);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

  // ---- living MANILA wallpaper: story mode everywhere, work mode (off by default) on the document reader ----------
  if (window.HansonWallpaper) {
    const work = document.body.classList.contains("lle-work");
    window.HansonWallpaper.mount({ theme: "manila", mode: work ? "work" : "story", fps: 30, scope: work ? "reader" : "story" });
  }

  // ---- glossary tooltips on a.gl (hover and keyboard focus; Escape closes) -----------------------------------------
  if (D && D.glossary) {
    const tip = document.createElement("div");
    tip.className = "gl-tip"; tip.id = "gl-tip"; tip.setAttribute("role", "tooltip"); tip.hidden = true;
    document.body.appendChild(tip);
    let cur = null;
    const show = (a) => {
      const id = (a.getAttribute("href") || "").split("#")[1]; const g = D.glossary[id]; if (!g) return;
      cur = a; tip.innerHTML = `<b>${esc(g.term)}</b>${esc(g.def)}`; tip.hidden = false; a.setAttribute("aria-describedby", "gl-tip");
      const r = a.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
      let x = r.left + window.scrollX, y = r.bottom + window.scrollY + 8;
      x = Math.max(12 + window.scrollX, Math.min(x, window.scrollX + document.documentElement.clientWidth - tw - 12));
      if (r.bottom + th + 12 > window.innerHeight && r.top > th + 12) y = r.top + window.scrollY - th - 8;
      tip.style.left = x + "px"; tip.style.top = y + "px";
    };
    const hide = () => { if (cur) cur.removeAttribute("aria-describedby"); cur = null; tip.hidden = true; };
    document.querySelectorAll("a.gl").forEach((a) => {
      a.addEventListener("mouseenter", () => show(a)); a.addEventListener("mouseleave", hide);
      a.addEventListener("focus", () => show(a)); a.addEventListener("blur", hide);
    });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") hide(); });
  }

  // ---- the stamp lands once when it scrolls into view (no scroll-jacking; still under reduced motion) -------------
  function landStamp(el) {
    if (rm.matches) return;
    el.classList.remove("is-landing"); void el.offsetWidth; el.classList.remove("is-armed"); el.classList.add("is-landing");
  }
  const hero = $("#hero-stamp");
  if (hero && "IntersectionObserver" in window && !rm.matches) {
    hero.classList.add("is-armed");
    const io = new IntersectionObserver((es) => { if (es.some((e) => e.isIntersecting)) { landStamp(hero); io.disconnect(); } }, { threshold: .6 });
    io.observe(hero);
  }

  // ---- error table filter -------------------------------------------------------------------------------------
  const filt = $("#cause-filter"), tbl = $("#errtable");
  if (filt && tbl) {
    const upd = () => {
      let n = 0; tbl.querySelectorAll("tbody tr").forEach((tr) => { const on = !filt.value || tr.dataset.cause === filt.value; tr.hidden = !on; n += on; });
      $("#filter-count").textContent = `Showing ${n} of ${tbl.querySelectorAll("tbody tr").length} wrong boxes.`;
    };
    filt.addEventListener("change", upd); upd();
  }

  // ---- copy the WISP paragraph ----------------------------------------------------------------------------------
  const cp = $("#wisp-copy");
  if (cp) cp.addEventListener("click", async () => {
    const t = $("#" + cp.dataset.target).textContent.replace(/\s+/g, " ").trim(), out = $("#wisp-copied");
    try { await navigator.clipboard.writeText(t); out.textContent = "Copied. Fill in the brackets before you use it."; }
    catch (e) { out.textContent = "Copy is blocked in this browser. Select the paragraph and copy it by hand."; }
  });

  // ---- the document reader ----------------------------------------------------------------------------------------
  const reader = $("#reader"), ctl = $("#reader-controls");
  if (!reader || !ctl) return;
  if (!D || !D.docs || !D.docs.length) {
    reader.innerHTML = '<p class="hl-panel">The document data did not load (data/site-data.js). Rebuild the site with <code>quarto render site</code>, which runs build_data.py first.</p>';
    return;
  }
  const byId = Object.fromEntries(D.docs.map((d) => [d.id, d]));
  const OK = new Set(["correct", "correct_null"]);
  const nOk = (d, k) => d.rows.filter((r) => OK.has(r[k])).length;
  const kind = (d) => `${d.style === "unseen" ? "new" : "familiar"} ${d.layout === "narrative" ? "email/note" : d.layout}`;
  const mistakes = D.docs.filter((d) => nOk(d, "aio") < d.rows.length);
  const CAPTION = { doc_003: "Familiar form", doc_026: "New free-text note", doc_046: "New table: a slip", doc_002: "Familiar email: invented date" };
  const WORD = { correct: "✓ Right", correct_null: "✓ Right to leave blank", wrong: "✗ Wrong value", hallucinated: "✗ Invented", missed: "✗ Left blank" };

  ctl.innerHTML = D.featured.map((id) => `<button type="button" class="btn-ghost" data-doc="${id}" aria-pressed="false">${id}<small>${esc(CAPTION[id] || kind(byId[id]))}</small></button>`).join("")
    + '<span class="ctl-sep" aria-hidden="true"></span>'
    + '<button type="button" class="btn-main" id="rd-random">Random document</button>'
    + `<button type="button" class="btn-ghost" id="rd-mistake">Show me a mistake <small>${mistakes.length} of ${D.docs.length} documents</small></button>`
    + '<label for="rd-pick">or pick any</label><select id="rd-pick">'
    + D.docs.map((d) => `<option value="${d.id}">${d.id} · ${kind(d)} · AI ${nOk(d, "aio")} of 9</option>`).join("") + "</select>";

  function renderText(d) {
    const rowOf = Object.fromEntries(d.rows.map((r, i) => [r.f, [r, i + 1]]));
    let out = "", at = 0;
    d.spans.forEach((sp) => {
      const [r, n] = rowOf[sp.f];
      out += esc(d.text.slice(at, sp.s));
      const body = esc(d.text.slice(sp.s, sp.e));
      if (sp.k === "trap") out += `<mark class="fld is-trap" title="Decoy: looks like an answer, is not">${body}<span class="fld-tag">decoy</span></mark>`;
      else {
        const bad = !OK.has(r.aio);
        out += `<mark class="fld${bad ? " is-bad" : ""}" data-f="${sp.f}">${body}<span class="fld-tag">${n} ${bad ? "✗" : "✓"}</span></mark>`;
      }
      at = sp.e;
    });
    return out + esc(d.text.slice(at));
  }

  function show(id, focusSel) {
    const d = byId[id] || D.docs[0];
    const ai = nOk(d, "aio"), ru = nOk(d, "ro");
    ctl.querySelectorAll("[data-doc]").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.doc === d.id)));
    $("#rd-pick").value = d.id;
    const how = d.method === "llm" ? (d.attempts > 1 ? `the AI answered on try ${d.attempts}` : "the AI answered first time")
      : `the AI failed the checks ${d.attempts} times, so the plain rules answered (fallback)`;
    $("#reader-status").innerHTML = `Showing <b>${d.id}</b>, a ${kind(d)} (SYNTHETIC). The AI got <b>${ai} of 9</b> boxes right; the plain rules got <b>${ru} of 9</b>.`;
    reader.innerHTML = `
      <section class="sheet-wrap" aria-labelledby="sheet-h">
        <span class="sheet-tab" id="sheet-h">${d.id} · ${kind(d)} · SYNTHETIC</span>
        <div class="sheet"><p class="stamp" aria-hidden="true"><span>Processed locally</span><span class="stamp-small">Nothing uploaded</span></p>
          <pre aria-label="The text the AI received">${renderText(d)}</pre></div>
        <p class="sheet-meta">The exact text pulled from the PDF, line by line. <a href="pdf/${d.id}.pdf">Open the original PDF (SYNTHETIC)</a>. For this document ${how}.</p>
      </section>
      <section class="results" aria-labelledby="res-h">
        <h2 id="res-h">What the AI filled in</h2>
        <p class="score-line"><span>AI: ${ai} of 9 right</span><span class="muted">Plain rules: ${ru} of 9</span></p>
        ${d.method === "llm" ? "" : `<p class="wtm">The AI's answer failed the automatic checks ${d.attempts} times, so the plain rules' answer was kept instead. The AI column shows what was kept.</p>`}
        <table class="data"><caption>${d.id}: each box, the answer key, the AI's answer and the plain rules' answer.</caption>
          <thead><tr><th scope="col">Box</th><th scope="col">Answer key</th><th scope="col">AI</th><th scope="col">Plain rules</th></tr></thead>
          <tbody>${d.rows.map((r, i) => {
            const aOk = OK.has(r.aio), rOk = OK.has(r.ro);
            return `<tr data-f="${r.f}"><th scope="row"><span class="fnum">${i + 1}</span>${esc(D.plain[r.f])}</th>
              <td class="v" data-l="Answer key">${esc(r.key || "(not stated)")}</td>
              <td class="v" data-l="AI">${esc(r.ai || "(blank)")}<br><span class="verdict ${aOk ? "ok" : "bad"}">${WORD[r.aio]}</span></td>
              <td class="v" data-l="Plain rules">${esc(r.rules || "(blank)")}<br><span class="verdict ${rOk ? "ok" : "bad"}">${WORD[r.ro]}</span></td></tr>`;
          }).join("")}</tbody></table>
      </section>`;
    // link table rows and highlights on hover
    reader.querySelectorAll("tr[data-f]").forEach((tr) => {
      const on = (v) => { tr.classList.toggle("is-hot", v); reader.querySelectorAll(`mark[data-f="${tr.dataset.f}"]`).forEach((m) => m.classList.toggle("is-hot", v)); };
      tr.addEventListener("mouseenter", () => on(true)); tr.addEventListener("mouseleave", () => on(false));
    });
    const st = reader.querySelector(".stamp"); if (st) landStamp(st);
    if (location.hash.slice(1) !== d.id) history.replaceState(null, "", "#" + d.id);
    if (focusSel) { const f = $(focusSel); f && f.focus(); }
  }
  const pick = (arr, not) => { const pool = arr.filter((d) => d.id !== not); return pool[Math.floor(Math.random() * pool.length)].id; };
  ctl.addEventListener("click", (e) => {
    const b = e.target.closest("button"); if (!b) return;
    const now = $("#rd-pick").value;
    if (b.dataset.doc) show(b.dataset.doc);
    else if (b.id === "rd-random") show(pick(D.docs, now));
    else if (b.id === "rd-mistake") show(pick(mistakes, now));
  });
  $("#rd-pick").addEventListener("change", (e) => show(e.target.value));
  window.addEventListener("hashchange", () => { const id = location.hash.slice(1); if (byId[id]) show(id); });
  const start = location.hash.slice(1);
  show(byId[start] ? start : D.featured[0]);
})();
